import{_ as a,o,c as d,af as c}from"./chunks/framework.zl0XNxp1.js";const p=JSON.parse('{"title":"南京旅行杂谈 - 2023","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/travel_record/NanJing.md","filePath":"2_articles/travel_record/NanJing.md"}'),r={name:"2_articles/travel_record/NanJing.md"};function t(i,e,l,n,h,_){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="南京旅行杂谈-2023" tabindex="-1">南京旅行杂谈 - 2023 <a class="header-anchor" href="#南京旅行杂谈-2023" aria-label="Permalink to &quot;南京旅行杂谈 - 2023&quot;">​</a></h1><h2 id="_4月29日-5月2日-☀️" tabindex="-1">4月29日 - 5月2日 ☀️ <a class="header-anchor" href="#_4月29日-5月2日-☀️" aria-label="Permalink to &quot;4月29日 - 5月2日 ☀️&quot;">​</a></h2><blockquote><p>因为记录博客时南京之旅已经过了整整两年，很多细节都忘记了，所以这次旅行记录就大概谈谈我当时的感受吧，不知道未来的我们看到这篇博客会不会掉眼泪呢🥰</p></blockquote><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>南京是我和女朋友第一次一起旅行的地方，从21年9月上大学开始，我们就保持了一年多一千多公里的异地，大一因为没钱加上疫情，每次都只有放寒暑假才能回家见面，大二疫情放开，我们一起商量在两个城市中间找一座城市去见面，这样两个人花钱都少而且快，在盯着那份中国地图看了好久后，两个没钱的小孩决定五一去南京见面。</p><h3 id="买票" tabindex="-1">买票 <a class="header-anchor" href="#买票" aria-label="Permalink to &quot;买票&quot;">​</a></h3><p>这两个没钱没时间但思念心切的小孩，只能顶着五一假期的巨大人流量去南京，提前14天放票开始抢，抢到最后一天也只抢到两张无座票，两个小孩都在火车上站了一晚上十个小时，刚到南京的时候一个比一个累，直接在酒店睡了一上午才出去逛。</p><h3 id="_4月29日" tabindex="-1">4月29日 <a class="header-anchor" href="#_4月29日" aria-label="Permalink to &quot;4月29日&quot;">​</a></h3><p>因为没钱，订的酒店离市中心非常非常远，第一天下午我们一起逛了明孝陵，我因为太累困的直接在明孝陵的板凳上睡着了，醒来后在明孝陵拍了我们的第一个游客纪念照哈哈，晚上在<code>科巷</code>吃了巨辣无比的成都菜(至今没想通为啥我俩要在南京吃成都菜)，买了带南京标签的网红奶茶，后面才发现哪个城市都有这奶茶，之后就又坐地铁公交回酒店了。</p><h3 id="_4月30日" tabindex="-1">4月30日 <a class="header-anchor" href="#_4月30日" aria-label="Permalink to &quot;4月30日&quot;">​</a></h3><p>第二天行程安排的满满当当，先去了<code>鸡鸣寺</code>、<code>玄武湖</code>和<code>南京城墙</code>，中午随便吃了点后去了<code>总统府</code>、<code>老门东</code>和<code>三七八巷</code>，买了非常坑人的<code>驴打滚</code>，还见证了南京贫民在市区的格格不入，看的我俩心情巨难受，晚上去了<code>秦淮河</code>和<code>夫子庙</code>，纯粹的人挤人，每个人之间连一个拳头都放不下，受不了想坐地铁回酒店，结果地铁站前排队排了半个多小时才进去，从这以后我俩发誓毕业后绝不在五一和国庆出去旅游😆。</p><h3 id="_5月1日" tabindex="-1">5月1日 <a class="header-anchor" href="#_5月1日" aria-label="Permalink to &quot;5月1日&quot;">​</a></h3><p>第一次出门旅游没经验，不知道南京的一些景点还要预约，前一天晚上约了半天的<code>南京大屠杀纪念馆</code>都没约上，最后想去现场碰下运气，发现人排的巨多无比，然后就直接坐地铁去了<code>慰安妇纪念馆</code>，之前都是在电视上看，那天第一次踏进真正存在过慰安妇的纪念馆，看着墙上的各种真实照片和物件，心里无比沉重，纪念馆里安静的氛围让我们真的代入了当时的情境，从纪念馆出来后迟迟没法缓过来，甚至从南京回来几天后都还能想起来那种沉重的感觉。中午在<code>科巷</code>买了一些小吃后就出发<code>先锋书店</code>，现在想起来我俩当时是真的精力旺盛，竟然是全程步行去的<code>先锋书店</code>，日均三万多步，在先锋书店拍了当时很满意的照片(在南京才刚开始接触摄影，后面发现当时的照片完全不能看哈哈)，还挂了我们手写的明信片，不知道现在还是否挂在那，还给好兄弟也挂了明信片。下午回去后本来打算在原来的酒店再住一晚，结果五一太火爆，酒店价格飙升到七八百，就在网上找了个比较偏但便宜的酒店，结果打车到了才发现，那酒店都不能叫偏，旁边简直荒无人烟，感觉在高速公路旁边开了家酒店的那种，然后又退掉后重新找了家市里价格还算可以的，打车到那里后两个人点了<code>鸭血粉丝汤</code>，现在想起来当时好可怜但非常幸福哈哈，也是那时候开始发誓，我一定要努力赚钱让以后我们的旅游不再为了价格而发愁，不再有明明喜欢但因为价格没法买的窘境，也再也不要坐晚上十几个小时的无座绿皮火车。</p><h3 id="_5月2日" tabindex="-1">5月2日 <a class="header-anchor" href="#_5月2日" aria-label="Permalink to &quot;5月2日&quot;">​</a></h3><p>这天的早上做了什么不太记得了，只记得中午在南京吃了我们俩人生中第一次<code>海底捞</code>(没钱的我们竟然在南京吃哈哈)，下午我们就去了火车站啦，在火车站两个小孩又很可怜的蹲在站里的最角落，默默等待着分别的到来，黛黛的火车晚点让我们在火车站又多呆了一会，那也是我们第一次因为分别而哭泣，看着黛黛下电梯后我又站在检票口，想起当时的心情好像很呆滞，明明上一秒还在拥抱的人下一秒就不能再看到，明明上一秒她还在我身边，结果现在只剩我一个人在这座城市。幸好我们的努力是有回报的，现在的我们终于再也不用体会那种感觉了，现在我们在一起，在某天彻底结束了长达四年的异地恋。</p><p><code>最后更新时间：2025-07-23 23:22:59</code></p>',16)])])}const u=a(r,[["render",t]]);export{p as __pageData,u as default};
